// In frontend/src/TripMap.js

import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Polyline, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { generateRainbowColors, generateColorGradient } from './colorUtils'; // Import color utils

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
    iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
    iconUrl: require('leaflet/dist/images/marker-icon.png'),
    shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// A custom component to update the map's view
const MapUpdater = ({ bounds }) => {
    const map = useMap();
    useEffect(() => {
        if (bounds && bounds.isValid()) {
            map.fitBounds(bounds, { padding: [25, 25] });
        }
    }, [bounds, map]);
    return null;
};

const TripMap = ({ groupData, timeRange }) => {
    const { logs, all_data, all_columns } = groupData;

    if (!logs || logs.length === 0) {
        return <div style={{ textAlign: 'center', padding: '20px' }}>No logs to display on map.</div>;
    }

    const rainbowColors = generateRainbowColors(logs.length);
    const polylines = [];
    let allPoints = [];

    logs.forEach((log, index) => {
        const logId = log.log_id;
        const data = all_data[logId] || [];
        const columns = all_columns[logId] || [];

        const latCol = columns.find(c => c.toLowerCase().includes('latitude'));
        const lonCol = columns.find(c => c.toLowerCase().includes('longitude'));

        if (!latCol || !lonCol) return; // Skip logs without GPS columns

        // Filter points based on the chart's visible time range
        const visiblePoints = data
            .filter(d => d.timestamp >= timeRange.min && d.timestamp <= timeRange.max && d[latCol] !== 0 && d[lonCol] !== 0)
            .map(d => [d[latCol], d[lonCol]]);

        if (visiblePoints.length > 0) {
            allPoints = [...allPoints, ...visiblePoints];
            polylines.push(
                <Polyline key={logId} positions={visiblePoints} pathOptions={{ color: rainbowColors[index], weight: 4, opacity: 0.8 }} />
            );
        }
    });

    if (allPoints.length === 0) {
        return <div style={{ textAlign: 'center', padding: '20px' }}>No GPS data in the selected time range.</div>;
    }

    const bounds = L.latLngBounds(allPoints);

    return (
        <MapContainer bounds={bounds} style={{ height: '400px', width: '100%' }}>
            <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            {polylines}
            <MapUpdater bounds={bounds} />
        </MapContainer>
    );
};

export default TripMap;
